"""Deploy the semantic layer generated by scripts/build_osi.py to Snowflake, each model twice, and check them all.

  1. gate      Snowflake holds the checked export (latest PUBLIC.LOAD_LOG entry = data/snowflake/tables.json)
  2. views     semantic/helper-views.sql (bridges and defined-class flags in GLP.SEMANTIC)
  3. OSI       semantic/{diabetes,japan}-market.osi.yaml via SYSTEM$CREATE_SEMANTIC_VIEW_FROM_OSSIE_YAML
               -> GLP.SEMANTIC.DIABETES_MARKET_OSI, JAPAN_MARKET_OSI
  4. native    semantic/{diabetes,japan}-market.sql -> GLP.SEMANTIC.DIABETES_MARKET, JAPAN_MARKET (with synonyms)
  5. read-back all views exported to OSI YAML (semantic/readback/), synonyms counted in each
  6. parity    two business questions through each US view (SEMANTIC_VIEW queries) must give the numbers the
               SPARQL queries gave on the graph (stored in tables.json by export_snowflake.py)
  7. verified  every verified query (semantic/verified-queries.json) runs on its views; those restating a parity
               question, and every Japan one (each restates a queries/jp-*.rq), give the graph's numbers
  8. SQL       queries/snowflake/*.sql, the questions that span both countries (no single semantic view holds
               them), give the graph's numbers

Usage: .venv-snowflake/bin/python scripts/deploy_semantic_view.py
"""
import json
import sys
from collections import Counter
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from load_snowflake import checked_export, connect  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent
SEMANTIC = ROOT / "semantic"
MODELS = {"DIABETES_MARKET": "diabetes-market", "JAPAN_MARKET": "japan-market"}
VIEWS = {(model, kind): f"GLP.SEMANTIC.{model}{'_OSI' if kind == 'osi' else ''}" for model in MODELS
         for kind in ("osi", "native")}
COST_CLASSES = ["Biguanide", "Sulfonylurea", "Thiazolidinedione", "DPP4Inhibitor", "SGLT2Inhibitor",
                "GLP1ReceptorAgonist", "LongActingInsulin"]  # as in queries/cost-per-claim-by-class.rq


def parity(cur, view, expected):
    """Differences between the view's answers and the graph's, per question (empty lists = parity)."""
    rows = cur.execute(f"""SELECT * FROM SEMANTIC_VIEW({view}
        DIMENSIONS specialty.specialty_name METRICS sglt2_claims, glp1_claims)""").fetchall()
    got = {name: [int(s), int(g)] for name, s, g in rows if name is not None and (s or g)}
    want = expected["sglt2-vs-glp1-by-specialty"]
    diff1 = sorted(k for k in got.keys() | want.keys() if got.get(k) != want.get(k))
    classes = ", ".join(f"'{c}'" for c in COST_CLASSES)
    rows = cur.execute(f"""SELECT * FROM SEMANTIC_VIEW({view}
        DIMENSIONS therapeutic_class.class_name METRICS class_claims, class_drug_cost
        WHERE therapeutic_class.class_id IN ({classes}) AND NOT product.is_combination)""").fetchall()
    got = {name: [int(c), round(float(cost))] for name, c, cost in rows}
    want = expected["cost-per-claim-by-class"]
    diff2 = sorted(k for k in got.keys() | want.keys() if got.get(k) != want.get(k))
    return {"sglt2-vs-glp1-by-specialty": diff1, "cost-per-claim-by-class": diff2}


def rows_of(cur, sql):
    cur.execute(sql)
    columns = [c[0].lower() for c in cur.description]
    return [dict(zip(columns, r)) for r in cur.fetchall()]


def differences(got, want, tolerance):
    """Keys whose numbers differ by more than the tolerance (the graph rounds; SPARQL computes in doubles)."""
    return sorted(str(k) for k in got.keys() | want.keys()
                  if k not in got or k not in want
                  or any(abs(float(a) - float(b)) > t for a, b, t in zip(got[k], want[k], tolerance)))


def million(x):
    return round(float(x) / 1e6)


def pct(x):
    return round(1000 * float(x)) / 10


def jp_expected(name, expected):
    """The graph's answer to the Japan verified query `name`, as {key: numbers}."""
    rows = {"jp_class_share_yen": "jp-class-share-yen", "jp_company_share_sglt2_dpp4": "jp-boehringer-share-by-class",
            "jp_age_profile_by_class": "jp-age-profile-by-class", "jp_generic_share_by_month": "jp-generic-share-by-month",
            "jp_glp1_monthly_uptake": "jp-glp1-monthly-uptake", "jp_sglt2_share_by_prefecture": "jp-sglt2-share-by-prefecture",
            "jp_glp1_products_by_category": "jp-glp1-by-japanese-category-reasoning"}[name]
    rows = expected[rows]
    return {
        "jp_class_share_yen": lambda: {r["class"]: (r["yenMillion"], r["sharePct"]) for r in rows
                                       if not r["class"].startswith("(")},
        "jp_company_share_sglt2_dpp4": lambda: {(r["class"], r["company"]): (r["yenMillion"], r["sharePct"]) for r in rows},
        "jp_age_profile_by_class": lambda: {r["class"]: (r["yenMillion"], r["age75plusPct"], r["femalePct"]) for r in rows},
        "jp_generic_share_by_month": lambda: {(r["class"], r["month"]): (r["genericPct"],) for r in rows},
        "jp_glp1_monthly_uptake": lambda: {(r["month"], r["substance"]): (r["yenMillion"],) for r in rows},
        "jp_sglt2_share_by_prefecture": lambda: {r["prefecture"]: (r["sglt2SharePct"], r["allYenMillion"]) for r in rows},
        "jp_glp1_products_by_category": lambda: {r["category"]: (r["products"],) for r in rows if r["country"] == "Japan"},
    }[name]()


def jp_got(name, rows):
    """The same answer from the rows of the verified query."""
    month = lambda d: d.strftime("%Y-%m")  # noqa: E731
    return {
        "jp_class_share_yen": lambda: {r["class_name"]: (million(r["class_value_yen"]), pct(r["market_share"]))
                                       for r in rows},
        "jp_company_share_sglt2_dpp4": lambda: {(r["class_name"], r["company"]): (million(r["class_value_yen"]),
                                                                                  pct(r["class_market_share"]))
                                                for r in rows if r["class_value_yen"] > 1e9},
        "jp_age_profile_by_class": lambda: {r["class_name"]: (million(r["age_class_value_yen"]),
                                                              pct(r["age_75plus_value_share"]), pct(r["female_value_share"]))
                                            for r in rows},
        "jp_generic_share_by_month": lambda: {(r["class_name"], month(r["month"])): (pct(r["month_generic_quantity_share"]),)
                                              for r in rows},
        "jp_glp1_monthly_uptake": lambda: {(month(r["month"]), r["active_substances"]): (million(r["month_class_value_yen"]),)
                                           for r in rows},
        "jp_sglt2_share_by_prefecture": lambda: {r["prefecture_name_ja"]: (pct(r["prefecture_sglt2_value_share"]),
                                                                           million(r["prefecture_value_yen_all"]))
                                                 for r in rows},
        "jp_glp1_products_by_category": lambda: {r["jp_class_name_ja"]: (r["product_count"],) for r in rows},
    }[name]()


def check_verified(cur, model, view, expected):
    """Every verified query runs; those that restate a parity question, and the Japan ones, give the graph's numbers."""
    problems = []
    for vq in json.loads((SEMANTIC / "verified-queries.json").read_text()):
        if vq["view"] != model:
            continue
        try:
            rows = rows_of(cur, vq["sql"].format(view=view))
        except Exception as exc:
            problems.append(f"{vq['name']}: {str(exc)[:200]}")
            continue
        if vq["name"].startswith("jp_"):
            if diff := differences(jp_got(vq["name"], rows), jp_expected(vq["name"], expected), (1, 0.1, 0.1)):
                problems.append(f"{vq['name']}: {len(diff)} rows differ from the graph, e.g. {diff[0]}")
        if vq["name"] == "sglt2_vs_glp1_by_specialty":
            got = {r["specialty_name"]: [int(r["sglt2_claims"]), int(r["glp1_claims"])]
                   for r in rows if r["specialty_name"] and (r["sglt2_claims"] or r["glp1_claims"])}
            if got != expected["sglt2-vs-glp1-by-specialty"]:
                problems.append(f"{vq['name']}: differs from the graph")
        if vq["name"] == "cost_per_claim_by_drug_class":  # the graph query lists 7 of the drug classes
            got = {r["class_name"]: [int(r["class_claims"]), round(float(r["class_drug_cost"]))] for r in rows}
            if any(got.get(k) != v for k, v in expected["cost-per-claim-by-class"].items()):
                problems.append(f"{vq['name']}: differs from the graph")
    return problems


def check_sql(cur, expected):
    """queries/snowflake/*.sql against the graph's answers to their SPARQL twins."""
    problems = []
    rows = rows_of(cur, (ROOT / "queries" / "snowflake" / "jp-vs-connecticut-class-mix.sql").read_text())
    got = {r["class_name"]: (r["japan_pct"], r["connecticut_pct"]) for r in rows}
    want = {r["class"]: (r["japanPct"], r["connecticutPct"]) for r in expected["jp-vs-connecticut-class-mix"]}
    if diff := differences(got, want, (0.1, 0.1)):
        problems.append(f"jp-vs-connecticut-class-mix: {len(diff)} classes differ, e.g. {diff[0]}")
    rows = rows_of(cur, (ROOT / "queries" / "snowflake" / "glp1-products-by-country.sql").read_text())
    got = {(r["country"], r["category"]): (r["products"],) for r in rows}
    want = {(r["country"], r["category"]): (r["products"],) for r in expected["jp-glp1-by-japanese-category-reasoning"]}
    if diff := differences(got, want, (0,)):
        problems.append(f"glp1-products-by-country: {len(diff)} rows differ, e.g. {diff[0]}")
    return problems


def main():
    manifest = checked_export()
    con = connect()
    cur = con.cursor()
    loaded = cur.execute("SELECT RDF_PROVENANCE FROM PUBLIC.LOAD_LOG ORDER BY LOADED_AT DESC LIMIT 1").fetchone()
    if not loaded or loaded[0] != manifest["rdf_provenance"]:
        sys.exit("Snowflake does not hold the checked export: run scripts/load_snowflake.py first")

    for _ in con.execute_string((SEMANTIC / "helper-views.sql").read_text()):
        pass
    print("helper views created")
    for model, file in MODELS.items():
        osi_yaml = (SEMANTIC / f"{file}.osi.yaml").read_text()
        print("OSI:", cur.execute("CALL SYSTEM$CREATE_SEMANTIC_VIEW_FROM_OSSIE_YAML('GLP.SEMANTIC', %s)",
                                  (osi_yaml,)).fetchone()[0])
        cur.execute((SEMANTIC / f"{file}.sql").read_text())
        print("native:", cur.fetchone()[0])

    report = {}
    (SEMANTIC / "readback").mkdir(exist_ok=True)
    for (model, kind), view in VIEWS.items():
        text = cur.execute("SELECT SYSTEM$READ_OSSIE_YAML_FROM_SEMANTIC_VIEW(%s)", (view,)).fetchone()[0]
        (SEMANTIC / "readback" / f"{view.split('.')[-1].lower()}.osi.yaml").write_text(text)
        # DESCRIBE: object_kind, object_name, parent_entity, property, property_value
        described = cur.execute(f"DESCRIBE SEMANTIC VIEW {view}").fetchall()
        objects = Counter(kind for kind, *_ in {(r[0], r[1], r[2]) for r in described})
        synonyms = sum(len(json.loads(r[4])) for r in described if r[3] == "SYNONYMS")
        diffs = parity(cur, view, manifest["parity"]) if model == "DIABETES_MARKET" else {}
        diffs["verified-queries"] = check_verified(cur, model, view, manifest["parity"])
        report[view] = {"objects": dict(objects), "synonyms": synonyms, "parity_differences": diffs}
        print(f"{view}: {synonyms} synonyms; parity: "
              + "; ".join(f"{q} {'OK' if not d else f'{len(d)} differ, e.g. {d[0]}'}" for q, d in diffs.items()))
    report["queries/snowflake"] = {"parity_differences": {"sql": check_sql(cur, manifest["parity"])}}
    print("queries/snowflake:", "; ".join(report["queries/snowflake"]["parity_differences"]["sql"]) or "OK")
    out = ROOT / "data" / "validation" / "semantic-view-check.json"
    out.write_text(json.dumps(report, indent=1, ensure_ascii=False))
    if any(d for r in report.values() for d in r["parity_differences"].values()):
        sys.exit("parity failed; see " + str(out.relative_to(ROOT)))
    print(f"all views match the graph; read-back in semantic/readback/, report in {out.relative_to(ROOT)}")
    con.close()


if __name__ == "__main__":
    main()
